\begin{gathered}
\begin{aligned}
s_{tx}(t) &= A\cos\left(2\pi\left(f_0 t + \frac{S}{2}t^2\right)\right) \\
s_{rx}(t) &= A'\cos\left(2\pi\left(f_0(t-t_0) + \frac{S}{2}(t-t_0)^2\right)\right) \\[2ex]
s_{mix}(t) &= AA'\cos\left(2\pi\left(f_0 t + \frac{S}{2}t^2\right)\right)\cos\left(2\pi\left(f_0(t-t_0) + \frac{S}{2}(t-t_0)^2\right)\right) \\
&= B\left\{\cos\left(2\pi\left(2f_0 t + St^2 - St_0 t + \varphi_1\right)\right) + \cos\left(2\pi\left(St_0 t + \varphi_2\right)\right)\right\}
\end{aligned}
\\[3ex]
\left[\, B = \frac{AA'}{2},\quad \varphi_1 = -f_0 t_0 + \frac{S}{2}t_0^2,\quad \varphi_2 = f_0 t_0 - \frac{S}{2}t_0^2 \,\right]
\end{gathered}
